function icons(){ $$('i[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PATHS[el.dataset.icon]||PATHS.info}</svg>`;});}
let workspaces=readWorkspaces(localStorage),KEY=dataKey(workspaces.active);
const PAGES={overview:'At a glance',explorer:'Explore connections',transactions:'Transactions',patterns:'Spending patterns',planner:'Card planner',data:'Statements & backups'};
const connections=new ConnectionExplorer();
let seed,db,importState=null,toastTimer,pendingDocument=null,importGeneration=0;
let state={page:'overview',explorerView:'ask',explorerSelection:null,explorerQuery:'',explorerDirection:'debit',accountFilter:'all',from:'',to:'',category:'all',scope:'all',chartMode:'spending',mix:'all',search:'',direction:'all',onlyReview:false,min:'',max:'',pageIndex:0,sort:'newest',planCats:Object.keys(CATEGORIES).filter(c=>CATEGORIES[c].card),annualSpend:null,pointValue:.5,fee:10000,gst:18,waiver:800000,bonusQuarters:0,rent:0};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));$('#save-status').textContent='Saved on this browser';}catch(err){$('#save-status').textContent='Changes in memory only';toast('Browser storage is full or disabled. Download a backup to keep your edits.');}}
function all(){return db.transactions.map(t=>effective(t,db.overrides,db.rules));}
function bounds(){const ds=db.transactions.map(t=>t.date).sort();return[ds[0]||'',ds.at(-1)||''];}
function resetDates(){[state.from,state.to]=bounds();state.category='all';state.scope='all';state.accountFilter='all';state.explorerSelection=null;state.pageIndex=0;}
function rows(){return all().filter(t=>(state.accountFilter==='all'||JSON.stringify([t.account,t.accountKey])===state.accountFilter)&&(!state.from||t.date>=state.from)&&(!state.to||t.date<=state.to)&&(state.category==='all'||t.category===state.category));}
function dateLabel(d,year=true){if(!d)return'—';return new Date(d+'T00:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',...(year?{year:'numeric'}:{}),timeZone:'UTC'});}
function monthLabel(m,year=false){return new Date(m+'-01T00:00:00Z').toLocaleDateString('en-IN',{month:'short',...(year?{year:'2-digit'}:{}),timeZone:'UTC'});}
const percent=(a,b)=>b?(a/b*100).toFixed(1)+'%':'0%';
function options(values,selected){return values.map(v=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(v)}</option>`).join('');}
function catOptions(selected){return options(Object.keys(CATEGORIES),selected);}
function heading(title,subtitle,eyebrow='YOUR MONEY, IN VIEW'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="period-stamp">${dateLabel(state.from)} — ${dateLabel(state.to)}</div></div>`;}
function filters(){return `<div class="period-shortcuts" aria-label="Quick date ranges"><button data-period="all">All history</button><button data-period="3">Last 3 months</button><button data-period="6">Last 6 months</button><span>Based on your latest statement</span></div><div class="filters"><span class="filter-label">Period</span><input aria-label="From date" type="date" id="filter-from" value="${e(state.from)}"><span class="filter-label">to</span><input aria-label="To date" type="date" id="filter-to" value="${e(state.to)}"><select id="filter-account" aria-label="Filter account"><option value="all">All accounts</option>${[...new Map(all().map(t=>[JSON.stringify([t.account,t.accountKey]),t])).entries()].map(([key,t])=>`<option value="${e(key)}" ${state.accountFilter===key?"selected":""}>${e(t.accountKey)} · ${t.account==='card'?'card':'bank'}</option>`).join('')}</select><select aria-label="Filter category" id="filter-category"><option value="all">All categories</option>${catOptions(state.category)}</select><button class="reset" data-action="reset-filters">Reset filters</button><span class="filtered-note">${rows().length.toLocaleString('en-IN')} transactions in view</span></div>`;}
function panelHead(title,subtitle='',right=''){return `<div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</div>`;}
function metric(title,value,detail,which,featured=false){return `<article class="metric ${featured?'featured':''}"><div class="metric-title">${title}${icon(which)}</div><div class="metric-value" title="${e(value)}">${value}</div><small>${detail}</small></article>`;}
function monthSeries(ts){return monthsBetween(state.from,state.to).slice(-36).map(key=>{const list=ts.filter(t=>t.date.startsWith(key));return {key,debit:sum(list.filter(t=>t.account==='bank'),'debit'),credit:sum(list.filter(t=>t.account==='bank'),'credit'),expense:sum(list.filter(t=>CATEGORIES[t.category]?.expense),'debit')};});}
function chart(ts){const data=monthSeries(ts),cash=state.chartMode==='cashflow',max=Math.max(1,...data.map(m=>cash?Math.max(m.debit,m.credit):m.expense));if(!data.length)return '<div class="empty">Import a statement to see monthly trends.</div>';return '<div class="trend-scroll"><div class="trend-chart" style="--columns:'+data.length+'">'+data.map(m=>'<button class="trend-month" data-month="'+m.key+'" aria-label="Explore '+monthLabel(m.key,true)+': '+(cash?'Money in '+money(m.credit)+', money out '+money(m.debit):money(m.expense)+' in identified purchases')+'"><span class="trend-tooltip">'+monthLabel(m.key,true)+'<b>'+(cash?'In '+money(m.credit)+'<br>Out '+money(m.debit):money(m.expense))+'</b><small>Click to see payments ↗</small></span><span class="trend-bars">'+(cash?'<span class="trend-bar incoming" style="height:'+m.credit/max*100+'%"></span><span class="trend-bar outgoing" style="height:'+m.debit/max*100+'%"></span>':'<span class="trend-bar purchase" style="height:'+m.expense/max*100+'%"></span>')+'</span><span class="trend-label">'+monthLabel(m.key)+'<small>'+m.key.slice(0,4)+'</small></span></button>').join('')+'</div></div><p class="panel-note">Hover, focus or tap a month to explore. '+(data.length===36?'Latest 36 months shown. ':'')+'First and last months may cover only part of the month.</p>';}
function categoryList(ts,limit=7,expenseOnly=false){const groups=grouped(ts.filter(t=>t.debit>0&&(!expenseOnly||CATEGORIES[t.category]?.expense)),'category'),total=sum(groups,'total');if(!groups.length)return '<div class="empty">No debit transactions in this view.</div>';return `<div class="category-topline"><div class="category-total">${money(total)}</div><small>${expenseOnly?'identified purchases':'all debit categories'}</small></div><div class="category-list">${groups.slice(0,limit).map(g=>`<button class="category-row" data-category="${e(g.key)}" title="Filter ${e(g.key)}"><span class="dot" style="background:${CATEGORIES[g.key]?.color||'#aaa'}"></span><span class="label">${e(g.key)}<span class="bar-track" style="display:block"><span class="bar-fill" style="display:block;width:${g.total/total*100}%;background:${CATEGORIES[g.key]?.color||'#aaa'}"></span></span></span><strong>${money(g.total)}<span class="share">${percent(g.total,total)}</span></strong></button>`).join('')}</div>${groups.length>limit?`<p class="panel-note" style="margin-top:16px">${groups.length-limit} more categories. View Transactions to explore all.</p>`:''}`;}
function merchants(ts,limit=6){const gs=grouped(ts.filter(t=>t.debit>0&&CATEGORIES[t.category]?.expense),'merchant').slice(0,limit);return gs.length?gs.map(g=>`<div class="merchant-row"><div class="merchant-letter">${e(g.key.slice(0,1))}</div><div><b>${e(g.key)}</b><small>${g.count} payments · ${e(g.rows[0].category)}</small></div><div class="value">${money(g.total)}<small>${money(g.total/g.count)} average</small></div></div>`).join(''):'<div class="empty">Categorize purchases to see merchants.</div>';}
function overview(ts){const s=stats(ts),series=monthSeries(ts),peak=series.reduce((a,b)=>b.expense>a.expense?b:a,{expense:0}),cats=grouped(ts.filter(t=>inScope(t,'purchases')),'category');
return heading('Your money, made clear.','A little clarity for your everyday decisions. Explore a chart to see the payments behind it.','YOUR PERSONAL MONEY PICTURE')+filters()+`<section class="overview-hero"><div class="hero-copy"><span class="hero-kicker">IDENTIFIED PURCHASES · SELECTED PERIOD</span><div class="hero-amount">${money(s.expense)}</div><p>What you bought, based on the categories so far.</p><button class="button" data-scope="purchases">Explore these purchases ${icon('arrow')}</button><small>Includes purchase categories from bank and card statements. Transfers, investments and card bill payments are excluded. Refunds are shown separately.</small></div><div class="hero-story"><span class="hero-orbit" aria-hidden="true">↗</span><span class="hero-kicker">THE BIGGER PICTURE</span><h2>Money out doesn’t<br>always mean money spent.</h2><p>Property payments and investments can make account activity look much larger than everyday purchases.</p><button data-action="money-map" class="hero-anchor">See where your bank money went ↓</button></div></section>
<div class="metrics overview-metrics">${metric('Bank money out',money(s.bankDebit),'All bank payments, including transfers','out')}${metric('Bank money in',money(s.bankCredit),'Salary, transfers, refunds and other credits','in')}${metric('Purchase payments',s.expenseCount.toLocaleString('en-IN'),'Categorized as purchases in this period','card')}<button class="metric review-metric" data-action="review"><div class="metric-title">Still needs your review ${icon('review')}</div><div class="metric-value">${money(s.unresolved)}</div><small>${s.reviewCount} unclear payments · Review now ↗</small></button></div>
<div class="two-col equal"><section class="panel">${panelHead('How your spending changes','Select a month to explore the payments.',`<div class="segmented"><button data-chart="spending" aria-pressed="${state.chartMode==='spending'}" class="${state.chartMode==='spending'?'active':''}">Purchases</button><button data-chart="cashflow" aria-pressed="${state.chartMode==='cashflow'}" class="${state.chartMode==='cashflow'?'active':''}">Money in / out</button></div>`)}<div class="trend-headline">${peak.expense?`<strong>${monthLabel(peak.key,true)}</strong><span>had the most identified purchases: ${money(peak.expense)}</span>`:'Your monthly story starts here.'}</div>${chart(ts)}<div class="legend">${state.chartMode==='cashflow'?'<span><i class="dot" style="background:#c5d8a6"></i>Money in</span><span><i class="dot" style="background:#486a50"></i>Money out</span>':'<span><i class="dot" style="background:#7c9b67"></i>Identified purchases</span>'}</div></section><section class="panel">${panelHead('What you spent on','Select a category to explore its payments.')}${spendingRing(ts)}</section></div>
<section class="panel money-map" id="money-map">${panelHead('Where did your bank money go?','Every rupee of bank outflow, grouped by its current category. Select a group to see the details.')}${bankFlow(ts)}</section>
<div class="two-col equal"><section class="panel">${panelHead('Places you spend most','Your largest identified purchase merchants.', '<button class="text-link" data-scope="purchases">Explore purchases ↗</button>')}${merchants(ts)}</section><section class="panel next-steps">${panelHead('Make your picture more complete','A few useful next steps.')}<button data-action="review"><span class="step-number">01</span><span><b>Give unclear payments a purpose</b><small>Review ${s.reviewCount} payments. Correct one merchant and apply the category to matching payments.</small></span><span>↗</span></button><button data-action="upload"><span class="step-number">02</span><span><b>See what’s inside your card bill</b><small>Import a card statement to see purchases behind ${money(s.cardSettlements)} in bill payments.</small></span><span>↗</span></button><button data-page-link="patterns"><span class="step-number">03</span><span><b>Find your recurring habits</b><small>Explore repeat payments and compare your categories across months.</small></span><span>↗</span></button></section></div>`;
}
function scopeMatch(t,scope){return scope==='bankPurchases'?t.account==='bank'&&inScope(t,'purchases'):scope==='bankReview'?t.account==='bank'&&inScope(t,'review'):inScope(t,scope);}
function clearTransactionFilters(){state.scope='all';state.search='';state.direction='all';state.onlyReview=false;state.min='';state.max='';state.pageIndex=0;}
function explore(scope='all'){clearTransactionFilters();state.scope=scope;navigate('transactions');}
function filteredTransactions(ts){return ts.filter(t=>scopeMatch(t,state.scope)&&(!state.search||(t.description+' '+t.merchant+' '+t.category+' '+t.source).toLowerCase().includes(state.search.toLowerCase()))&&(state.direction==='all'||(state.direction==='debit'?t.debit>0:t.credit>0))&&(!state.onlyReview||t.review&&t.debit>0)&&(!state.min||(t.debit+t.credit)>=+state.min)&&(!state.max||(t.debit+t.credit)<=+state.max)).sort((a,b)=>state.sort==='largest'?(b.debit+b.credit)-(a.debit+a.credit):state.sort==='oldest'?a.date.localeCompare(b.date)||a.row-b.row:b.date.localeCompare(a.date)||b.row-a.row);}
function transactions(ts){const list=filteredTransactions(ts),size=35,maxPage=Math.max(0,Math.ceil(list.length/size)-1);state.pageIndex=Math.min(state.pageIndex,maxPage);const shown=list.slice(state.pageIndex*size,(state.pageIndex+1)*size);
return heading('Every payment has a story.','Search, filter and correct suggested categories. Use a transaction’s detail button to apply a category to the same merchant.')+filters()+`<section class="panel table-panel"><div class="table-heading">${panelHead('Transaction explorer',`${list.length.toLocaleString('en-IN')} matches · Debits ${money(sum(list,'debit'))} · Credits ${money(sum(list,'credit'))}`,`<button class="button small" data-action="export">${icon('download')}Export visible</button>`)}</div><div class="search-tools"><select id="tx-scope" aria-label="Payment group">${Object.entries({...SCOPES,bankPurchases:"Bank purchases",bankReview:"Bank payments to review"}).map(([key,label])=>`<option value="${key}" ${state.scope===key?"selected":""}>${label}</option>`).join("")}</select><input id="tx-search" type="search" placeholder="Search merchant, description or source…" value="${e(state.search)}" aria-label="Search transactions"><select id="tx-direction" aria-label="Transaction direction"><option value="all">Debits & credits</option><option value="debit" ${state.direction==='debit'?'selected':''}>Debits only</option><option value="credit" ${state.direction==='credit'?'selected':''}>Credits only</option></select><select id="tx-sort" aria-label="Sort transactions"><option value="newest">Newest first</option><option value="oldest" ${state.sort==='oldest'?'selected':''}>Oldest first</option><option value="largest" ${state.sort==='largest'?'selected':''}>Largest first</option></select><input id="tx-min" type="number" min="0" placeholder="Min ₹" value="${e(state.min)}" aria-label="Minimum transaction amount"><input id="tx-max" type="number" min="0" placeholder="Max ₹" value="${e(state.max)}" aria-label="Maximum transaction amount"><label><input id="tx-review" type="checkbox" ${state.onlyReview?'checked':''}>Needs review</label></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Merchant / counterparty</th><th>Category</th><th>Status</th><th style="text-align:right">Debit</th><th style="text-align:right">Credit</th><th></th></tr></thead><tbody>${shown.map(t=>`<tr><td class="date">${dateLabel(t.date)}</td><td><span class="merchant-name" title="${e(t.merchant)}">${e(t.merchant)}</span><span class="description" title="${e(t.description)}">${e(t.description)}</span></td><td><select aria-label="Category for ${e(t.merchant)} on ${t.date}" data-tx-category="${t.id}">${catOptions(t.category)}</select></td><td><span class="pill ${t.review?'warning':t.classification==='Edited'?'manual':''}">${t.review?'Review':t.classification}</span></td><td class="num">${t.debit?preciseMoney(t.debit):'—'}</td><td class="num amount-credit">${t.credit?preciseMoney(t.credit):'—'}</td><td><button class="row-info" data-detail="${t.id}" aria-label="Details for ${e(t.merchant)}">${icon('info')}</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No transactions match these filters.</div></td></tr>'}</tbody></table></div><div class="pagination"><span>${list.length?state.pageIndex*size+1:0}–${Math.min((state.pageIndex+1)*size,list.length)} of ${list.length.toLocaleString('en-IN')} transactions</span><div class="buttons"><button class="button small" data-page-step="-1" ${state.pageIndex===0?'disabled':''}>Previous</button><button class="button small" data-page-step="1" ${state.pageIndex===maxPage?'disabled':''}>Next</button></div></div></section>`;}
function patterns(ts){const rec=recurring(ts),months=monthsBetween(state.from,state.to).slice(-18),cats=grouped(ts.filter(t=>t.debit&&CATEGORIES[t.category]?.expense),'category'),max=Math.max(1,...cats.flatMap(c=>months.map(m=>sum(c.rows.filter(t=>t.date.startsWith(m)),'debit'))));
 const subscriptions=ts.filter(t=>t.category==='Subscriptions'&&t.debit),food=ts.filter(t=>['Dining & food','Groceries'].includes(t.category)&&t.debit);
return heading('See what repeats.','Explore monthly habits and recurring-payment candidates. Similar amounts are a clue, not proof of a subscription.')+filters()+`<div class="metrics">${metric('Digital subscriptions',money(sum(subscriptions,'debit')),`${subscriptions.length} identified payments in this period`,'data',true)}${metric('Food & groceries',money(sum(food,'debit')),`${food.length} identified payments in this period`,'card')}${metric('Repeat-payment candidates',String(rec.length),'Seen in at least three calendar months','patterns')}${metric('Distinct purchase merchants',String(new Set(ts.filter(t=>t.debit&&CATEGORIES[t.category]?.expense).map(t=>t.merchant)).size),'Based on normalized merchant names','transactions')}</div><section class="panel">${panelHead('The shape of your spending','Identified purchase categories by month. Darker cells show a larger amount.')}<div class="table-scroll"><div class="heatmap" style="--months:${months.length||1}"><div class="heat-row head"><span>Category</span>${months.map(m=>`<span>${monthLabel(m,true)}</span>`).join('')}</div>${cats.map(c=>`<div class="heat-row"><span>${e(c.key)}</span>${months.map(m=>{const v=sum(c.rows.filter(t=>t.date.startsWith(m)),'debit');return `<button class="heat-cell" style="background:rgba(124,155,103,${v?.08+.65*v/max:.025})" data-heat-month="${m}" data-heat-category="${e(c.key)}" title="${e(c.key)} · ${monthLabel(m,true)}: ${money(v)}">${v?compact(v):'—'}</button>`;}).join('')}</div>`).join('')}</div></div><p class="panel-note" style="margin-top:17px">${months.length===18?'Showing the latest 18 months. ':''}The first and last month may be partial. Unclear transfers and merchant payments are excluded until categorized.</p></section><h2 class="section-title">Repeat-payment candidates</h2><div class="recurring-grid">${rec.slice(0,12).map(g=>`<article class="recurring-card"><div class="row"><div class="merchant-letter">${e(g.key[0])}</div><span class="pill">${g.months} months</span></div><div class="name">${e(g.key)}</div><div class="amount">${money(g.median)}</div><div class="meta">Typical payment · ${g.count} payments<br>${money(g.total)} total in this period<br>${e(g.rows[0].category)}</div><div class="month-dots" aria-label="Active months">${months.map(m=>`<span class="${g.rows.some(t=>t.date.startsWith(m))?'filled':''}" title="${monthLabel(m,true)}"></span>`).join('')}</div></article>`).join('')||'<div class="empty">No repeat-amount candidates found in this date range.</div>'}</div><div class="note-box">A candidate needs payments in at least three months and at least 65% of its amounts within 15% of the median. Regular cafe purchases can also match; this does not imply an automatic debit mandate.</div>`;}
function planner(ts){const potential=ts.filter(t=>t.debit>0&&state.planCats.includes(t.category)),observed=sum(potential,'debit'),spend=state.annualSpend===null?observed:state.annualSpend,maxQ=Math.min(4,Math.floor(spend/400000));state.bonusQuarters=Math.min(state.bonusQuarters,maxQ);const points=Math.floor(spend/150)*5,bonus=state.bonusQuarters*10000,gross=(points+bonus)*state.pointValue,fee=spend>=state.waiver?0:state.fee*(1+state.gst/100),rentFee=state.rent*12*.01*(1+state.gst/100),net=gross-fee-rentFee,gap=Math.max(0,state.waiver-spend),pct=Math.min(100,spend/state.waiver*100),s=stats(ts);
return heading('Make the annual fee earn its place.','An editable Diners Black Metal scenario grounded in the purchases you can identify. Bank narrations do not contain card acceptance or merchant-category codes.','CREDIT CARD PLANNING')+filters()+`<div class="insight-strip warning"><div class="insight-icon">${icon('info')}</div><div><h3>Use this as a scenario, not confirmed qualifying spend</h3><p>${money(s.unresolved)} of debit outflow still needs review. ${money(s.cardSettlements)} in credit-card settlements hides the underlying purchases. Rent, transfers, property payments, investments and cash withdrawals are excluded from the default spending estimate.</p></div></div><div class="planner-grid"><section class="panel">${panelHead('Start with the spending you can identify','Choose candidate categories, then adjust the annual scenario.')}<div class="category-choices">${Object.keys(CATEGORIES).filter(c=>CATEGORIES[c].expense&&c!=='Rent'&&c!=='Taxes & fees').map(c=>`<label><input type="checkbox" data-plan-category="${e(c)}" ${state.planCats.includes(c)?'checked':''}>${e(c)}</label>`).join('')}</div><div class="note-box">Selected source spend: <b>${money(observed)}</b>. These payments could potentially move to a card if the merchant accepts it and the transaction qualifies. The date window is not annualized.</div><div class="form-grid"><label class="field">Annual eligible spend to model (₹)<input id="plan-spend" type="number" min="0" step="1000" value="${spend.toFixed(0)}"><small>Use about 12 months of spending. Edit this for your future estimate.</small></label><label class="field">Reward point value (₹)<select id="plan-point"><option value="0.5" ${state.pointValue===.5?'selected':''}>0.50 · products / vouchers ceiling</option><option value="0.3" ${state.pointValue===.3?'selected':''}>0.30 · conservative scenario</option><option value="1" ${state.pointValue===1?'selected':''}>1.00 · flights / hotels</option></select><small>Count only redemption value you expect to use.</small></label><label class="field">Annual fee before GST (₹)<input type="number" id="plan-fee" min="0" value="${state.fee}"></label><label class="field">GST on fees (%)<input type="number" id="plan-gst" min="0" max="100" value="${state.gst}"></label><label class="field">Annual spend waiver target (₹)<input type="number" id="plan-waiver" min="1" value="${state.waiver}"></label><label class="field">Verified ₹4L calendar quarters<select id="plan-quarters">${Array.from({length:maxQ+1},(_,i)=>`<option value="${i}" ${state.bonusQuarters===i?'selected':''}>${i} qualifying quarter${i===1?'':'s'}</option>`).join('')}</select><small>Manual choice. Your annual amount alone does not prove a quarterly milestone.</small></label><label class="field full-width">Optional monthly rent through card (₹)<input type="number" id="plan-rent" min="0" value="${state.rent}"><small>Models a 1% bank rent fee plus GST, before platform charges. Rent is not added to qualifying spend or reward points here.</small></label></div><button class="text-link" style="margin-top:16px" data-action="plan-reset">Use selected source spend again</button><details class="disclosure"><summary>Assumptions and official terms</summary><p>Benchmark: 5 points per ₹150 of eligible retail spending, ₹8 lakh annual renewal waiver, ₹10,000 fee before tax, and 10,000 bonus points for each qualifying ₹4 lakh calendar quarter. Products and vouchers offer up to ₹0.50 per point; flights and hotels offer ₹1 per point. Defaults checked 15 Oct 2026.</p><p>This approximation excludes SmartBuy multipliers, welcome memberships, category caps, transaction-level rounding, reward exclusions, partner charges and redemption availability. A lower-fee card can also earn rewards, so the net figure is not the advantage over alternatives. The first-year joining fee can still apply even if the following renewal is waived.</p><p>Rent earns no points. Maintenance payment treatment and fee-waiver eligibility must be verified with HDFC for the payment route. <a class="source-link" href="https://www.hdfc.bank.in/credit-cards/diners-club-black-metal-edition-credit-card" target="_blank" rel="noopener">HDFC card benefits</a> · <a class="source-link" href="https://www.hdfc.bank.in/credit-cards/diners-club-black-metal-edition-credit-card/fees-and-charges" target="_blank" rel="noopener">Fees and charges</a></p></details></section><div><section class="panel planner-result"><div class="eyebrow" style="color:#a9bf94">YOUR EDITABLE SCENARIO</div><h2>Potential annual card spend</h2><div class="big">${money(spend)}</div><div class="sub">${money(gap)} ${gap?'below the renewal-waiver target':'remaining to target'}</div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="row"><span>${pct.toFixed(0)}% of target</span><b>${money(state.waiver)}</b></div><hr><div class="row"><span>Base reward points, approximate</span><b>${points.toLocaleString('en-IN')}</b></div><div class="row"><span>Quarterly bonus points, selected</span><b>${bonus.toLocaleString('en-IN')}</b></div><div class="row"><span>Modelled reward value</span><b>${money(gross)}</b></div><div class="row"><span>Renewal fee incl. entered GST</span><b>− ${money(fee)}</b></div><div class="row"><span>Optional yearly rent fee estimate</span><b>− ${money(rentFee)}</b></div><hr><div class="sub">Reward value less modelled fees</div><div class="big" style="font-size:32px;margin-top:12px">${money(net)}</div><p class="footnote">${net<0?'Rewards in this scenario do not cover the modelled fees.':'A positive result means estimated rewards exceed the modelled fees. Compare with rewards from a lower-fee card too.'} This is a planning estimate, not a guarantee of rewards or waiver eligibility.</p></section><div class="note-box">The ₹8 lakh benchmark is approximately <b>₹66,667 per month</b> of qualifying spend. Adding a costly payment route just to meet a threshold can reduce the benefit.</div></div></div>`;}
function dataPage(){return heading('A statement today. A habit tomorrow.','Import new statements, merge overlapping periods and keep your category corrections. Common account references and UPI addresses are masked where detected.','YOUR DATA')+`<div class="two-col"><section class="panel">${panelHead('Import another statement','PDFs, statement photos, Numbers, Excel, CSV and TSV. Restore a dashboard backup with JSON.')}<button class="upload-area" data-action="upload" style="width:100%">${icon('upload')}<h3>Choose a statement or drop it here</h3><p>.pdf · .jpg · .png · .webp · .numbers · .xlsx · .xls · .csv · .tsv · backup .json<br>Parsed in your browser. No upload to a server.</p></button><div class="note-box">For the same account, use the same account label when importing. Exact overlapping transactions are skipped. Different accounts can share a date and amount without being treated as duplicates.</div><div class="data-actions"><button class="button" data-action="backup">${icon('download')}Download backup</button><button class="button" data-action="export">Export transaction CSV</button></div></section><section class="panel">${panelHead('About this analysis','A few definitions that keep the numbers useful.')}<p class="small-muted"><b>Bank cash flow</b> includes all debits and credits from accounts labelled as bank accounts. Imported credit-card rows are excluded from these cash-flow totals.</p><p class="small-muted"><b>Identified purchases</b> includes debit transactions assigned to expense categories, including insurance and taxes. Transfers, investments, property payments, cash withdrawals and card bill payments are excluded.</p><p class="small-muted"><b>Review categories</b> are unclear transfers or merchant payments. They are not assumed to be purchases. You can categorize them or confirm that they are transfers.</p><p class="small-muted"><b>Credits are gross inflows.</b> Merchant refunds appear separately and are not automatically netted against purchases. Bank settlements cannot reveal what you bought on a credit card.</p></section></div><section class="panel">${panelHead('Imported statements',`${db.sources.length} source${db.sources.length===1?'':'s'} · ${db.transactions.length.toLocaleString('en-IN')} unique transactions in this browser`)}<div class="sources-list">${db.sources.map(s=>`<article class="source-card"><div><div class="source-name">${e(s.name)}</div><div class="source-meta">${e(s.accountKey||s.account)} · ${e(s.sheet||'Table')}<br>${dateLabel(s.from)} — ${dateLabel(s.to)} · ${s.count.toLocaleString('en-IN')} parsed rows${s.added!==undefined?` · ${s.added} added, ${s.duplicates||0} overlapping rows skipped`:''}</div><div class="source-totals"><span>Source debits<b>${money(s.debit)}</b></span><span>Source credits<b>${money(s.credit)}</b></span></div>${s.check?.available?`<details class="disclosure"><summary>Reconciliation and source details</summary><p>Running-balance checks: ${s.check.count}. Differences: ${s.check.errors.length}. Opening balance derived from the first transaction: ${preciseMoney(s.check.opening)}. Last stated balance: ${preciseMoney(s.check.closing)}.</p><p>Source totals include every parsed row in that file. Overlapping rows are skipped in dashboard totals, so source totals should not be added together.</p>${s.check.errors.length?`<p class="warning-text">Review the original statement near source rows ${s.check.errors.slice(0,8).map(x=>x.row).join(', ')} before relying on cash-flow totals. Transactions were preserved.</p>`:''}</details>`:'<p class="small-muted">Running-balance reconciliation unavailable: no bank balance column.</p>'}</div><span class="badge-check" style="${s.check?.errors?.length?'background:#faeee2;color:#ac7444':''}">${s.check?.available?s.check.errors.length?'Balance differences to review':'Running balances reconcile':'Imported without balance check'}</span></article>`).join('')||'<div class="empty">No statements. Import a file to begin.</div>'}</div></section><section class="panel" style="margin-top:20px">${panelHead('Storage and backup','The initial statement is part of this owner-private dashboard. Later uploads and edits stay in this browser.')}<p class="small-muted">Export a JSON backup to move your work to another browser. CSV exports include transactions but do not preserve categorization rules. Clearing browser storage can remove later imports. PDFs, scanned PDFs and clear JPG, PNG or WebP statement photos are supported through local text extraction. Always check recognized amounts and dates. Numbers support has been verified with your supplied statement; workbook structures can vary.</p><div class="data-actions">${workspaces.active==='personal'?'<button class="button" data-action="restore-original">Restore original statement</button>':''}<button class="button danger" data-action="clear">Clear dashboard in this browser</button></div></section>`;}
function renderWorkspacePicker(){const el=$('#workspace-switch');if(el)el.innerHTML=workspaces.items.map(w=>'<option value="'+e(w.id)+'" '+(w.id===workspaces.active?'selected':'')+'>'+e(w.name)+'</option>').join('');const label=$('#analysis-name');if(label)label.textContent=workspaces.items.find(w=>w.id===workspaces.active)?.name||'My spending';}
function emptyOverview(){return heading('A fresh statement. A new perspective.','Upload a bank or credit-card statement to turn transactions into a picture you can explore.','START YOUR ANALYSIS')+'<section class="panel empty-analysis"><div class="empty-analysis-icon">↗</div><h2>Your data tells the story.</h2><p>Upload a spreadsheet, PDF or photo. Check the extracted transactions, then explore spending, recurring payments and connections.</p><button class="button primary" data-action="upload">Choose a statement</button><div class="upload-formats">PDF · scanned PDF · JPG · PNG · WebP · Excel · CSV · Numbers</div><div class="analysis-steps"><div><b>01 · Upload</b><span>Files are processed on your device.</span></div><div><b>02 · Check</b><span>Review columns, amounts and balances.</span></div><div><b>03 · Explore</b><span>Follow categories and merchants back to payments.</span></div></div><p class="panel-note">INR statements with a readable transaction table. Scans and photos need a clear image; unfamiliar layouts may need corrections.</p></section>';}
function newAnalysisDialog(){$('#import-body').innerHTML='<div class="dialog-head"><div><div class="eyebrow">SEPARATE DATA, SEPARATE INSIGHTS</div><h2 id="import-title">Start a new analysis.</h2><p>Your current analysis stays available in the switcher.</p></div><button class="close-dialog" data-close="import-dialog" aria-label="Close">×</button></div><label class="field">Analysis name<input id="new-analysis-name" maxlength="60" placeholder="e.g. Family expenses or HDFC account"></label><div class="note-box">This creates an empty analysis in this browser. Import INR statements from one or more accounts, using a different account label for each. Download a backup to use it on another device.</div><div class="dialog-actions"><button class="button" data-close="import-dialog">Cancel</button><button class="button primary" data-action="create-analysis">Create analysis</button></div>';$('#import-dialog').showModal();$('#new-analysis-name').focus();}
function switchAnalysis(id){if(!workspaces.items.some(w=>w.id===id))return;try{localStorage.setItem(KEY,JSON.stringify(db));const nextKey=dataKey(id),stored=localStorage.getItem(nextKey),next=stored?validBackup(JSON.parse(stored)):id==='personal'?structuredClone(seed):emptyAnalysis();const nextWorkspaces={...workspaces,active:id};localStorage.setItem(WORKSPACES_KEY,JSON.stringify(nextWorkspaces));KEY=nextKey;db=next;workspaces=nextWorkspaces;clearTransactionFilters();state.explorerQuery='';resetDates();navigate('overview');toast('Analysis switched.');}catch{toast('Could not switch analyses. Download a backup and check browser storage.');renderWorkspacePicker();}}
function createAnalysis(){const name=$('#new-analysis-name').value.trim();if(!name){$('#new-analysis-name').focus();return;}const id='analysis-'+crypto.randomUUID();try{localStorage.setItem(KEY,JSON.stringify(db));localStorage.setItem(dataKey(id),JSON.stringify(emptyAnalysis()));const next={active:id,items:[...workspaces.items,{id,name}]};localStorage.setItem(WORKSPACES_KEY,JSON.stringify(next));workspaces=next;KEY=dataKey(id);db=emptyAnalysis();clearTransactionFilters();state.explorerQuery='';resetDates();$('#import-dialog').close();navigate('overview');toast('Your empty analysis is ready.');}catch{toast('Could not create an analysis. Download a backup and check browser storage.');}}
function render(){state.page=PAGES[location.hash.slice(1)]?location.hash.slice(1):state.page;const ts=rows();renderWorkspacePicker();$('#page-label').textContent=PAGES[state.page];$$('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===state.page);if(a.dataset.page===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const n=all().filter(t=>t.review&&t.debit).length;$('#nav-review').textContent=n?n.toLocaleString('en-IN'):'';
 $('#main').innerHTML=state.page==='explorer'?heading('Follow the connections.','Ask about your spending, explore the connections, and follow every answer to its statement rows.','YOUR STATEMENT, CONNECTED')+filters()+`<div class="kg-tabs" role="group" aria-label="Explorer view"><button data-explorer-view="ask" class="${state.explorerView==='ask'?'active':''}" aria-pressed="${state.explorerView==='ask'}">Ask & connect</button><button data-explorer-view="browse" class="${state.explorerView==='browse'?'active':''}" aria-pressed="${state.explorerView==='browse'}">Browse connections</button></div>`+(state.explorerView==='ask'?connections.render(ts,workspaces.active):renderExplorer(ts,{selection:state.explorerSelection,query:state.explorerQuery,direction:state.explorerDirection})):state.page==='overview'?(!db.transactions.length?emptyOverview():overview(ts)):state.page==='transactions'?transactions(ts):state.page==='patterns'?patterns(ts):state.page==='planner'?planner(ts):dataPage();icons();if(state.page==='explorer'&&state.explorerView==='ask')connections.mount($('.connect'));}
function navigate(page){state.page=page;location.hash=page;render();window.scrollTo({top:0,behavior:'smooth'});}
function monthFilter(month,category=null){const[lo,hi]=bounds();state.from=month+'-01';const[y,m]=month.split('-').map(Number);state.to=new Date(Date.UTC(y,m,0)).toISOString().slice(0,10);if(lo&&state.from<lo)state.from=lo;if(hi&&state.to>hi)state.to=hi;if(category)state.category=category;state.pageIndex=0;render();}
function download(name,content,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csvCell(v){let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportCSV(){const list=state.page==='transactions'?filteredTransactions(rows()):rows(),header=['Date','Merchant','Description','Category','Debit INR','Credit INR','Balance INR','Account label','Source','Classification'];const lines=list.map(t=>[t.date,t.merchant,t.description,t.category,t.debit,t.credit,t.balance??'',t.accountKey,t.source,t.classification]);download(`spend-insights-${state.from||'all'}-${state.to||'all'}.csv`,'\uFEFF'+[header,...lines].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast(`${list.length} transactions exported.`);}
function detail(id){const t=all().find(x=>x.id===id);if(!t)return;$('#detail-body').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">TRANSACTION DETAIL</div><h2 id="detail-title">${e(t.merchant)}</h2><p>${dateLabel(t.date)} · ${e(t.accountKey)}</p></div><button class="close-dialog" data-close="detail-dialog" aria-label="Close detail">×</button></div><div class="detail-grid"><div><small>Debit</small><span>${preciseMoney(t.debit)}</span></div><div><small>Credit</small><span>${preciseMoney(t.credit)}</span></div><div class="full"><small>Sanitized statement narration</small><div class="detail-description">${e(t.description)}</div></div><div class="full"><small>Category suggestion</small><span>${e(t.reason)}</span></div><div class="full"><small>Source</small><span>${e(t.source)} · ${t.sourcePage?'page '+e(t.sourcePage)+' · ':''}${t.extractedWithOCR?'recognized ':''}table row ${e(t.row)}</span></div></div><label class="field">Category<select id="detail-category">${catOptions(t.category)}</select></label><div class="dialog-actions"><label><input type="checkbox" id="apply-merchant">Apply to all ${t.debit?'debit':'credit'} payments for this merchant</label><button class="button primary" data-save-detail="${id}">Save category</button></div><p class="panel-note" style="margin-top:15px">Saving also confirms the payment’s purpose. Merchant rules will apply to matching future imports. Common references and UPI addresses are masked where detected.</p>`;$('#detail-dialog').showModal();icons();}
function validBackup(x){if(!x||x.version!==1||!Array.isArray(x.transactions)||!Array.isArray(x.sources)||!x.overrides||!x.rules)throw Error('This is not a Spend Insights backup.');if(x.transactions.length>100000)throw Error('This backup is too large.');for(const t of x.transactions){if(!parseDate(t.date)||typeof t.id!=='string'||!/^[A-Za-z0-9_-]{1,160}$/.test(t.id)||typeof t.source!=='string'||typeof t.accountKey!=='string'||!Number.isInteger(t.row)||t.row<1||(t.sourcePage!==undefined&&(!Number.isInteger(t.sourcePage)||t.sourcePage<1))||typeof t.merchant!=='string'||typeof t.description!=='string'||!Object.hasOwn(CATEGORIES,t.category)||!Number.isFinite(t.debit)||!Number.isFinite(t.credit)||t.debit<0||t.credit<0||t.debit&&t.credit||!['bank','card'].includes(t.account))throw Error('This backup contains an invalid transaction.');}for(const c of [...Object.values(x.overrides),...Object.values(x.rules)])if(!Object.hasOwn(CATEGORIES,c))throw Error('The backup contains an unknown category.');return x;}
function showImportError(err,file){if(['PDF_PASSWORD_REQUIRED','PDF_PASSWORD_INCORRECT'].includes(err.code)){pendingDocument=file;$('#import-body').innerHTML='<div class="dialog-head"><h2 id="import-title">Unlock this statement.</h2><button class="close-dialog" data-close="import-dialog" aria-label="Close">×</button></div><p class="panel-note">The password is used only in this browser and is not saved.</p>'+(err.code==='PDF_PASSWORD_INCORRECT'?'<div class="error-box">That password did not unlock the file. Try again.</div>':'')+'<label class="field">PDF password<input id="pdf-password" type="password" autocomplete="off"></label><div class="dialog-actions"><button class="button" data-close="import-dialog">Cancel</button><button class="button primary" data-action="unlock-pdf">Unlock PDF</button></div>';$('#pdf-password').focus();return;}pendingDocument=null;$('#import-body').innerHTML='<div class="dialog-head"><div><h2 id="import-title">This statement needs a different approach.</h2><p>Try a clearer image, a straight crop of the transaction table, or the bank’s CSV/Excel export.</p></div><button class="close-dialog" data-close="import-dialog" aria-label="Close import">×</button></div><div class="error-box">'+e(err.message||'The format could not be read.')+'</div><button class="button" data-close="import-dialog">Close</button>';}
async function openFile(file,password){if(!file)return;if(file.size>20*1024*1024){toast('Choose a statement smaller than 20 MB.');return;}const generation=++importGeneration;importState=null;$('#import-body').innerHTML='<div class="dialog-head"><div><h2 id="import-title">Reading your statement…</h2><p>'+e(file.name)+'</p></div><button class="close-dialog" data-close="import-dialog" aria-label="Cancel reading">×</button></div><div class="loading import-progress" id="import-progress" role="status">Opening the file on your device…</div>';if(!$('#import-dialog').open&&!$('#import-dialog').hasAttribute('open'))$('#import-dialog').showModal();
try{if(/\.json$/i.test(file.name)){const restored=validBackup(JSON.parse(await file.text()));if(generation!==importGeneration)return;importState={backup:restored,name:file.name};$('#import-body').innerHTML='<div class="dialog-head"><div><div class="eyebrow">RESTORE A BACKUP</div><h2 id="import-title">Bring your analysis back.</h2><p>'+e(file.name)+'</p></div><button class="close-dialog" data-close="import-dialog" aria-label="Close import">×</button></div><div class="note-box">This backup has '+restored.transactions.length.toLocaleString('en-IN')+' transactions and '+restored.sources.length+' statements. It replaces the current analysis. Other analyses stay as they are.</div><div class="dialog-actions"><button class="button" data-close="import-dialog">Cancel</button><button class="button primary" data-action="confirm-backup">Restore backup</button></div>';return;}
 let tables={},meta={};
 if(/\.(pdf|png|jpe?g|webp)$/i.test(file.name)){const {readStatementDocument}=await import('./pdf-import.mjs');meta=await readStatementDocument(file,{password,onProgress:progress=>{if(generation!==importGeneration)return;const el=$('#import-progress');if(el)el.textContent=(progress.stage==='ocr'?'Recognizing text':'Reading statement')+(progress.page?' · page '+progress.page+' of '+progress.pages:'')+'. Keep this tab open; scanned pages may take a little longer.';}});tables={'Extracted table':meta.rows};}
 else{if(!/\.(numbers|xlsx|xls|csv|tsv)$/i.test(file.name))throw Error('Choose PDF, JPG, PNG, WebP, Numbers, Excel, CSV or TSV.');const isText=/\.(csv|tsv)$/i.test(file.name);const workbook=XLSX.read(isText?await file.text():await file.arrayBuffer(),{type:isText?'string':'array',cellDates:true,raw:true});for(const name of workbook.SheetNames)tables[name]=XLSX.utils.sheet_to_json(workbook.Sheets[name],{header:1,defval:null,raw:true});}
 if(generation!==importGeneration)return;pendingDocument=null;const sheetNames=Object.keys(tables);if(!sheetNames.length)throw Error('No readable table was found.');let sheet=sheetNames[0],score=-1;for(const name of sheetNames){const d=detectMapping(tables[name]);if(d.score>score){sheet=name;score=d.score;}}
 importState={tables,sheetNames,name:file.name,sourceId:'import-'+hash(file.name+Date.now()),sheet,account:'bank',accountKey:'Main bank',dateOrder:'DMY',sign:'debit-positive',mode:'merge',usedOCR:!!meta.usedOCR,rowLocations:meta.rowLocations||[],warnings:meta.warnings||[],rawPage:0,rawOpen:false,reviewed:false};selectImportSheet(sheet);renderImport();
}catch(err){if(generation===importGeneration)showImportError(err,file);}}
function selectImportSheet(name){importState.sheet=name;importState.rows=importState.tables[name];const d=detectMapping(importState.rows);importState.header=d.header;importState.map=d.map;importState.layout=d.map.amount>=0&&d.map.debit<0&&d.map.credit<0?'signed':'split';importState.reviewed=false;importState.rawPage=0;}
function previewImport(){const map={...importState.map};if(importState.layout==='split')map.amount=-1;else{map.debit=-1;map.credit=-1;}const result=parseRows(importState.rows,{...importState,map,source:importState.name,sourceId:importState.sourceId,accountKey:importState.accountKey.trim()||'Main bank'});result.transactions=result.transactions.map(t=>({...t,...(importState.rowLocations[t.row-1]?.page?{sourcePage:importState.rowLocations[t.row-1].page}:{}),...(importState.usedOCR?{extractedWithOCR:true}:{})}));return result;}
function renderImport(){const s=importState;if(!s||s.backup)return;const result=previewImport();s.parsed=result;const ts=result.transactions,check=reconcile(ts);s.check=check;const duplicate=mergeTransactions(db.transactions,ts).duplicate;const valid=s.map.date>=0&&s.map.description>=0&&(s.layout==='signed'?s.map.amount>=0:s.map.debit>=0||s.map.credit>=0)&&ts.length>0&&!(result.schemaErrors?.length)&&!!s.accountKey.trim();$('#import-body').innerHTML=renderImportView(s,{result,check,duplicate,valid,dateLabel});}
function confirmImport(){const s=importState;if(!s?.parsed)return;const ts=s.parsed.transactions;const needsReview=s.usedOCR||s.warnings?.length||s.parsed.counts.invalid>0||(s.check?.available&&s.check.errors.length>0)||s.parsed.issues?.some(i=>i.severity==='warning');if(!ts.length||s.parsed.schemaErrors?.length||!s.accountKey.trim()||(needsReview&&!s.reviewed))return;const replacing=s.mode==='replace';if(replacing&&!confirm('Replace all current transactions with this statement? Your category rules will be kept.'))return;const result=mergeTransactions(replacing?[]:db.transactions,ts);if(!result.added){toast('Every transaction already exists. Nothing was added.');$('#import-dialog').close();return;}const ds=ts.map(t=>t.date).sort(),sourceId=ts[0].sourceId;const source={id:sourceId,name:s.name,usedOCR:!!s.usedOCR,sheet:s.sheet,account:s.account,accountKey:s.accountKey,count:ts.length,from:ds[0],to:ds.at(-1),debit:sum(ts,'debit'),credit:sum(ts,'credit'),check:s.check,added:result.added,duplicates:result.duplicate,skipped:s.parsed.counts,importedAt:new Date().toISOString().slice(0,10)};db.transactions=result.transactions;db.sources=replacing?[source]:[...db.sources,source];save();resetDates();$('#import-dialog').close();state.explorerSelection=null;state.explorerQuery='';navigate('explorer');toast(`${result.added} transactions added; ${result.duplicate} overlaps skipped.`);}
document.addEventListener('click',ev=>{const t=ev.target.closest('button,a,[data-month]');if(!t)return;if(t.dataset.explorerView){state.explorerView=t.dataset.explorerView;render();return;}if(t.dataset.close){if(t.dataset.close==='import-dialog'){importGeneration++;pendingDocument=null;}$('#'+t.dataset.close).close();return;}if(t.hasAttribute('data-explorer-clear')){state.explorerSelection=null;state.explorerQuery='';render();return;}if(t.dataset.explorerKind){state.explorerSelection={kind:t.dataset.explorerKind,key:t.dataset.explorerKey};render();return;}if(t.dataset.explorerDirection){state.explorerDirection=t.dataset.explorerDirection;state.explorerSelection=null;render();return;}if(t.hasAttribute('data-explorer-export')){download('statement-connections.json',JSON.stringify(buildGraph(state.explorerSelection?.kind==='question'?selectExplorerRows(searchExplorerRows(rows(),state.explorerQuery,state.explorerDirection),state.explorerSelection,state.explorerDirection):searchExplorerRows(rows(),state.explorerQuery,state.explorerDirection),{direction:state.explorerDirection}),null,2),'application/json');return;}if(t.dataset.rawStep){importState.rawPage=Math.max(0,(importState.rawPage||0)+Number(t.dataset.rawStep));importState.rawOpen=true;renderImport();return;}if(t.dataset.pageLink){navigate(t.dataset.pageLink);return;}if(t.dataset.chart){state.chartMode=t.dataset.chart;render();return;}if(t.dataset.mix){state.mix=t.dataset.mix;render();return;}if(t.dataset.period){resetDates();if(t.dataset.period!=='all'&&state.to){const d=new Date(state.to+'T00:00:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-Number(t.dataset.period)+1);state.from=[bounds()[0],d.toISOString().slice(0,10)].sort().at(-1);}clearTransactionFilters();render();return;}if(t.dataset.scope){explore(t.dataset.scope);return;}if(t.dataset.month){monthFilter(t.dataset.month);explore(state.chartMode==='spending'?'purchases':'bankActivity');return;}if(t.dataset.heatMonth){monthFilter(t.dataset.heatMonth,t.dataset.heatCategory);explore('purchases');return;}if(t.dataset.category){state.category=t.dataset.category;explore('all');return;}if(t.dataset.pageStep){state.pageIndex+=+t.dataset.pageStep;render();return;}if(t.dataset.detail){detail(t.dataset.detail);return;}if(t.dataset.saveDetail){const tx=db.transactions.find(x=>x.id===t.dataset.saveDetail),cat=$('#detail-category').value;db.overrides[tx.id]=cat;if($('#apply-merchant').checked)db.rules[tx.merchant+'|'+(tx.debit?'debit':'credit')]=cat;save();$('#detail-dialog').close();render();toast('Category saved.');return;}
 switch(t.dataset.action){case'new-analysis':newAnalysisDialog();break;case'create-analysis':createAnalysis();break;case'unlock-pdf':{const file=pendingDocument,password=$('#pdf-password').value;$('#pdf-password').value='';openFile(file,password);break;}case'money-map':$('#money-map').scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;case'upload':$('#file-input').value='';$('#file-input').click();break;case'backup':download('spend-insights-backup.json',JSON.stringify(db,null,2),'application/json');toast('Backup downloaded.');break;case'export':exportCSV();break;case'reset-filters':resetDates();state.search='';state.direction='all';state.onlyReview=false;state.min='';state.max='';render();break;case'review':clearTransactionFilters();state.category='all';state.onlyReview=true;navigate('transactions');break;case'plan-reset':state.annualSpend=null;render();break;case'confirm-import':confirmImport();break;case'confirm-backup':db=importState.backup;save();resetDates();$('#import-dialog').close();navigate('overview');toast('Backup restored.');break;case'clear':if(confirm('Clear transactions and category edits in this analysis? Download a backup first if you want to keep them.')){db={version:1,transactions:[],sources:[],overrides:{},rules:{}};save();resetDates();render();toast('Dashboard cleared on this browser.');}break;case'restore-original':if(workspaces.active!=='personal')break;if(confirm('Restore the original statement and remove later imports and edits from this browser?')){db=structuredClone(seed);save();resetDates();render();toast('Original statement restored.');}break;}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.id==='workspace-switch'){switchAnalysis(el.value);return;}if(el.id==='import-reviewed'){importState.reviewed=el.checked;renderImport();return;}if(el.dataset.rawRow!==undefined){importState.rows[Number(el.dataset.rawRow)][Number(el.dataset.rawCol)]=el.value;importState.rawOpen=true;importState.reviewed=false;renderImport();return;}if(el.id==='file-input'){openFile(el.files[0]);return;}if(el.dataset.txCategory){db.overrides[el.dataset.txCategory]=el.value;save();render();toast('Category updated.');return;}if(el.dataset.map){importState.reviewed=false;importState.map[el.dataset.map]=+el.value;renderImport();return;}if(el.dataset.import){importState.reviewed=false;const k=el.dataset.import;if(k==='sheet')selectImportSheet(el.value);else if(k==='header'){importState.rawPage=0;importState.header=Math.max(0,Math.min(importState.rows.length-1,+el.value-1));importState.map=detectMapping([importState.rows[importState.header]]).map;}else{importState[k]=el.value;if(k==='account'&&['Main bank','Credit card'].includes(importState.accountKey))importState.accountKey=el.value==='bank'?'Main bank':'Credit card';}renderImport();return;}if(el.dataset.planCategory){state.planCats=el.checked?[...state.planCats,el.dataset.planCategory]:state.planCats.filter(c=>c!==el.dataset.planCategory);state.annualSpend=null;render();return;}const changes={'filter-account':'accountFilter','tx-scope':'scope','filter-from':'from','filter-to':'to','filter-category':'category','tx-direction':'direction','tx-sort':'sort','tx-min':'min','tx-max':'max'};if(changes[el.id]){state[changes[el.id]]=el.value;if(state.from&&state.to&&state.from>state.to){state.to=state.from;toast('End date adjusted to the start date.');}state.pageIndex=0;render();return;}if(el.id==='tx-review'){state.onlyReview=el.checked;state.pageIndex=0;render();return;}const plans={'plan-spend':'annualSpend','plan-point':'pointValue','plan-fee':'fee','plan-gst':'gst','plan-waiver':'waiver','plan-quarters':'bonusQuarters','plan-rent':'rent'};if(plans[el.id]){const val=Math.max(el.id==='plan-waiver'?1:0,Number(el.value)||0);state[plans[el.id]]=el.id==='plan-gst'?Math.min(100,val):val;render();}});
let searchTimer,explorerTimer;document.addEventListener('input',ev=>{if(ev.target.id==='explorer-search'){state.explorerQuery=ev.target.value;state.explorerSelection=null;clearTimeout(explorerTimer);const cursor=ev.target.selectionStart;explorerTimer=setTimeout(()=>{render();const el=$('#explorer-search');if(el){el.focus();try{el.setSelectionRange(cursor,cursor);}catch{}}},200);return;}if(ev.target.id==='tx-search'){state.search=ev.target.value;state.pageIndex=0;clearTimeout(searchTimer);const cursor=ev.target.selectionStart;searchTimer=setTimeout(()=>{render();const el=$('#tx-search');if(el){el.focus();try{el.setSelectionRange(cursor,cursor);}catch{}}},180);}});
document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.dataset.month&&ev.target.tagName!=='BUTTON'){ev.preventDefault();monthFilter(ev.target.dataset.month);}});
window.addEventListener('hashchange',()=>{state.page=PAGES[location.hash.slice(1)]?location.hash.slice(1):'overview';render();});
$('#import-dialog').addEventListener('close',()=>{if(!$('#import-dialog').open){importGeneration++;pendingDocument=null;}});
$('#import-dialog').addEventListener('cancel',()=>{importGeneration++;pendingDocument=null;});
for(const id of ['import-dialog','detail-dialog'])$('#'+id).addEventListener('click',ev=>{if(ev.target===ev.currentTarget){const r=ev.currentTarget.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.currentTarget.close();}});
let dragDepth=0;document.addEventListener('dragenter',ev=>{if(!ev.dataTransfer?.types?.includes('Files'))return;ev.preventDefault();if(++dragDepth===1){const overlay=document.createElement('div');overlay.className='drop-overlay';overlay.id='drop-overlay';overlay.innerHTML='<div>Drop your statement<br><small style="font-size:13px;opacity:.7">PDF, photo, spreadsheet or analysis backup</small></div>';document.body.append(overlay);}});document.addEventListener('dragover',ev=>{if(ev.dataTransfer?.types?.includes('Files'))ev.preventDefault();});document.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;$('#drop-overlay')?.remove();}});document.addEventListener('drop',ev=>{ev.preventDefault();dragDepth=0;$('#drop-overlay')?.remove();if(ev.dataTransfer?.files?.length)openFile(ev.dataTransfer.files[0]);});
async function init(){try{seed=validBackup(await(await fetch('seed.json',{cache:'no-store'})).json());db=workspaces.active==='personal'?structuredClone(seed):emptyAnalysis();try{const saved=localStorage.getItem(KEY);if(saved)db=validBackup(JSON.parse(saved));}catch{toast('Saved data could not be read. Restore a backup before adding transactions.');}resetDates();state.page=PAGES[location.hash.slice(1)]?location.hash.slice(1):'overview';render();}catch(err){$('#main').innerHTML=`<div class="error-box">The dashboard could not load its initial data. ${e(err.message)} Refresh the page to try again.</div>`;}}
icons();await init();
